  'settings.modelProvider.help.capabilities': '- **Yapılandırılmış çıktı**: Çıktı alanları, türleri ve yapısı üzerinde JSON Şeması kısıtlamalarını destekler.\n- **Yerel web araması**: Model API\'sinin yerleşik web arama yeteneğini destekler.\n- **Konuşma ortası sistem mesajları**: Konuşma sırasında sistem talimatları eklemeyi destekler.\n\nModelin desteklemediği yetenekleri etkinleştirmeyin.',
